{
  "claims": [
    {
      "id": "CLAIM-001",
      "statement": "陈姐（ROLE-CHEN）表示，活动到店后她的工作流程是：先核对会员范围、参与门店和门店要做的事，再跟同事说明、确认人员和执行安排；执行中收集顾客问题和门店反馈，不清楚的找运营核对，结束后整理执行情况。",
      "kind": "fact",
      "evidence_status": "reported",
      "qualifiers": [],
      "evidence": [
        {
          "meeting_id": "6c1d37b4-9a0c-5106-8e00-9852640f4ea4",
          "message_id": "MSG-02617",
          "quote": "活动到店先核对会员范围、参与门店和门店要做的事，再跟同事说明、确认人员和执行安排；执行中收集顾客问题和门店反馈，不清楚的找运营核对，结束后整理执行情况。"
        }
      ],
      "conflict_ids": [],
      "review": {"status": "pending", "note": ""}
    },
    {
      "id": "CLAIM-002",
      "statement": "陈姐表示，券的发放和核销是两个环节，发放记录不能替代核销记录。",
      "kind": "fact",
      "evidence_status": "reported",
      "qualifiers": [],
      "evidence": [
        {
          "meeting_id": "6c1d37b4-9a0c-5106-8e00-9852640f4ea4",
          "message_id": "MSG-02617",
          "quote": "券的发放和核销是两个环节，发放记录不能替代核销记录。"
        }
      ],
      "conflict_ids": [],
      "review": {"status": "pending", "note": ""}
    },
    {
      "id": "CLAIM-003",
      "statement": "陈姐表示，活动执行确认在门店人员，她不代门店人员点头。",
      "kind": "opinion",
      "evidence_status": "reported",
      "qualifiers": ["这是陈姐对自己权限范围的说明"],
      "evidence": [
        {
          "meeting_id": "6c1d37b4-9a0c-5106-8e00-9852640f4ea4",
          "message_id": "MSG-02617",
          "quote": "执行确认在门店人员，我不代他们点头。"
        }
      ],
      "conflict_ids": [],
      "review": {"status": "pending", "note": ""}
    },
    {
      "id": "CLAIM-004",
      "statement": "陈姐表示，她不能单独改变公司的考核规则，具体由谁来确定规则，她本人不掌握，也不能替其他部门确认。",
      "kind": "fact",
      "evidence_status": "reported",
      "qualifiers": ["陈姐自称不掌握考核规则制定者的信息"],
      "evidence": [
        {
          "meeting_id": "6c1d37b4-9a0c-5106-8e00-9852640f4ea4",
          "message_id": "MSG-02617",
          "quote": "考核规则这块，我不能单独改变公司的考核规则，具体由谁来定，我这边不掌握，也不能替其他部门确认。"
        }
      ],
      "conflict_ids": [],
      "review": {"status": "pending", "note": ""}
    },
    {
      "id": "CLAIM-005",
      "statement": "陈姐表示，预算和合同需要王经理参与决定。",
      "kind": "opinion",
      "evidence_status": "reported",
      "qualifiers": ["陈姐在回应访谈者关于预算和合同需谁参与的问题时说的"],
      "evidence": [
        {
          "meeting_id": "6c1d37b4-9a0c-5106-8e00-9852640f4ea4",
          "message_id": "MSG-02617",
          "quote": "预算和合同还是按之前说的，要王经理参与。"
        }
      ],
      "conflict_ids": [],
      "review": {"status": "pending", "note": ""}
    },
    {
      "id": "CLAIM-006",
      "statement": "陈姐确认，访谈者复述的关于活动到店核对、执行确认和考核规则的内容与她的说法一致。",
      "kind": "fact",
      "evidence_status": "reported",
      "qualifiers": ["陈姐仅用'基本对得上'笼统回应，不视为对复述中每一条的逐条确认"],
      "evidence": [
        {
          "meeting_id": "6c1d37b4-9a0c-5106-8e00-9852640f4ea4",
          "message_id": "MSG-02617",
          "quote": "你复述的这些，跟我说的基本对得上"
        }
      ],
      "conflict_ids": [],
      "review": {"status": "pending", "note": ""}
    },
    {
      "id": "CLAIM-007",
      "statement": "老周（ROLE-ZHOU）在访谈开始时要求访谈者先说明要接哪些系统和了解哪些数据，把要核实的问题说清楚。",
      "kind": "fact",
      "evidence_status": "reported",
      "qualifiers": ["这是老周在访谈开始时的提问，不代表问题已经回答"],
      "evidence": [
        {
          "meeting_id": "c4a59a18-4bff-535c-a011-dd0dd0d508fd",
          "message_id": "MSG-02618",
          "quote": "你们这次想接哪些系统、了解哪些数据？先把要核实的问题说清楚。"
        }
      ],
      "conflict_ids": [],
      "review": {"status": "pending", "note": ""}
    }
  ]
}
